81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    /**
85	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
86	     * including this owner). Derived at read time and not persisted; an owner with no household
87	     * counts as a household of one. Feeds the household factor of the membership points.
