229	    protected Set<Pet> getPetsInternal() {
230	        if (this.pets == null) {
231	            this.pets = new HashSet<>();
232	        }
233	        return this.pets;
234	    }
235	
236	    protected void setPetsInternal(Set<Pet> pets) {
237	        this.pets = pets;
238	    }
239	
240	    public List<Pet> getPets() {
241	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
242	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
243	        return Collections.unmodifiableList(sortedPets);
244	    }
245	
246	    public void setPets(List<Pet> pets) {
247	        this.pets = new HashSet<>(pets);
248	    }
249	
250	    public void addPet(Pet pet) {
251	        getPetsInternal().add(pet);
252	        pet.setOwner(this);
253	    }
254	
255	    /**
256	     * Return the Pet with the given name, or null if none found for this Owner.
257	     *
258	     * @param name to test
259	     * @return true if pet name is already in use
260	     */
261	    public Pet getPet(String name) {
262	        return getPet(name, false);
263	    }
264	
265	    /**
266	     * Return the Pet with the given name, or null if none found for this Owner.
267	     *
268	     * @param name to test
269	     * @return true if pet name is already in use
270	     */
271	    public Pet getPet(String name, boolean ignoreNew) {
272	        name = name.toLowerCase();
273	        for (Pet pet : getPetsInternal()) {
274	            if (!ignoreNew || !pet.isNew()) {
275	                String compName = pet.getName();
276	                compName = compName.toLowerCase();
277	                if (compName.equals(name)) {
278	                    return pet;
279	                }
280	            }
281	        }
282	        return null;
283	    }
284	
285	    public Pet getPet(Integer petId) {
286	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
287	    }
288	
289	    @Override
290	    public String toString() {
291	        return new ToStringCreator(this)
292	
293	            .append("id", this.getId())
294	            .append("new", this.isNew())
295	            .append("lastName", this.getLastName())
296	            .append("firstName", this.getFirstName())
297	            .append("address", this.address)
298	            .append("city", this.city)
299	            .append("telephone", this.telephone)
300	            .toString();
301	    }
302	}
