80	 */
81	
82	@RestController
83	@CrossOrigin(exposedHeaders = "errors, content-type")
84	@RequestMapping("/api")
85	public class OwnerRestControllerV1 implements OwnersApi {
86	
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Carries the welcome notification enqueued for each newly created owner. On a successful create a
91	     * single line is emitted on this dedicated {@code NOTIFY} logger naming the owner's id and
92	     * {@code memberId}, so the downstream welcome flow can be triggered without an
93	     * implementation-specific hook.
94	     */
95	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
96	
97	    /**
98	     * Serializes {@link OwnerCreatedEvent}s to the JSON carried on the {@code AUDIT} logger. A single
99	     * shared, thread-safe mapper so every structured audit event is rendered identically.
100	     */
101	    private static final ObjectMapper AUDIT_MAPPER = new ObjectMapper();
102	
103	    /**
104	     * Monotonically increasing sequence assigned to each owner create, carried as the {@code seq} of
105	     * the emitted {@link OwnerCreatedEvent} so the ordering of creates can be reconstructed from the
106	     * audit stream. Held per JVM and incremented atomically so concurrent creates receive distinct,
107	     * strictly increasing values.
108	     */
109	    private static final AtomicLong CREATE_SEQUENCE = new AtomicLong();
110	
111	    private final ClinicService clinicService;
112	
113	    private final OwnerMapper ownerMapper;
114	
115	    private final PetMapper petMapper;
116	
117	    private final VisitMapper visitMapper;
118	
119	    private final TelephoneNormalizer telephoneNormalizer;
120	
121	    private final AddressNormalizer addressNormalizer;
122	
123	    private final EmailNormalizer emailNormalizer;
124	
125	    private final DisposableEmailDomains disposableEmailDomains;
126	
127	    private final Sha256Hasher sha256Hasher;
128	
129	    private final Soundex soundex;
130	
131	    private final IdempotencyKeyStore idempotencyKeyStore;
132	
133	    public OwnerRestControllerV1(ClinicService clinicService,
134	                                 OwnerMapper ownerMapper,
135	                                 PetMapper petMapper,
136	                                 VisitMapper visitMapper,
137	                                 TelephoneNormalizer telephoneNormalizer,
138	                                 AddressNormalizer addressNormalizer,
139	                                 EmailNormalizer emailNormalizer,
140	                                 DisposableEmailDomains disposableEmailDomains,
141	                                 Sha256Hasher sha256Hasher,
142	                                 Soundex soundex,
143	                                 IdempotencyKeyStore idempotencyKeyStore) {
144	        this.clinicService = clinicService;
145	        this.ownerMapper = ownerMapper;
146	        this.petMapper = petMapper;
147	        this.visitMapper = visitMapper;
148	        this.telephoneNormalizer = telephoneNormalizer;
149	        this.addressNormalizer = addressNormalizer;
150	        this.emailNormalizer = emailNormalizer;
151	        this.disposableEmailDomains = disposableEmailDomains;
152	        this.sha256Hasher = sha256Hasher;
153	        this.soundex = soundex;
154	        this.idempotencyKeyStore = idempotencyKeyStore;
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
160	        Collection<Owner> owners;
161	        if (lastName != null) {
162	            owners = this.clinicService.findOwnerByLastName(lastName);
163	        } else {
164	            owners = this.clinicService.findAllOwners();
165	        }
166	        if (owners.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
175	        return withOwner(ownerId, owner ->
176	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
177	    }
178	
179	    /**
180	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
181	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
182	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
183	     */
184	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
189	        String idempotencyKey = currentIdempotencyKey();
190	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
191	            .map(this.clinicService::findOwnerById);
192	        if (existing.isPresent()) {
193	            return ownerResponse(existing.get(), HttpStatus.OK);
194	        }
195	        Owner owner = createOwner(ownerFieldsDto);
196	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
197	        return ownerResponse(owner, HttpStatus.CREATED);
198	    }
199	
200	    /**
201	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
202	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
203	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
204	     * originally created owner.
205	     *
206	     * @return the request's idempotency key, or {@code null} when none was supplied
207	     */
208	    private String currentIdempotencyKey() {
209	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
210	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
211	        }
212	        return null;
213	    }
214	
215	    /**
216	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
217	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
218	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
219	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
220	     * then respond" and the persisted owner is available to callers that need it beyond the response.
221	     *
222	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
223	     * @return the persisted owner, with its derived fields populated
224	     */
225	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
226	        normalizeAddress(ownerFieldsDto);
227	        rejectBlankOwnerFields(ownerFieldsDto);
228	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
229	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
230	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
231	        rejectCityAtCapacity(ownerFieldsDto.getCity());
232	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
233	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
234	        rejectDailyRegistrationLimit(registrationDate);
235	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
236	        ownerFieldsDto.setTelephone(normalizedTelephone);
237	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
238	        ownerFieldsDto.setEmail(normalizedEmail);
239	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
240	        owner.setRegistrationDate(registrationDate);
241	        owner.setMemberId(memberId(owner));
242	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
243	        owner.setHouseholdId(householdId(owner));
244	        rejectDuplicateIdentity(owner);
245	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
246	        this.clinicService.saveOwner(owner);
247	        owner.setHouseholdSize(householdSize(owner));
248	        auditOwnerCreated(owner);
249	        enqueueWelcomeNotification(owner);
250	        return owner;
251	    }
252	
253	    /**
254	     * Enqueues the welcome notification for a just-created owner by emitting a single line on the
255	     * dedicated {@code NOTIFY} logger carrying the owner's id and {@code memberId}. Held separate from
256	     * the audit trail ({@link #auditOwnerCreated(Owner)}) so the welcome flow has its own single home
257	     * and the create pipeline reads as "make the owner, audit it, then welcome it".
258	     *
259	     * @param owner the persisted owner just created, with its derived fields populated
260	     */
261	    private void enqueueWelcomeNotification(Owner owner) {
262	        NOTIFY.info("Welcome notification enqueued: id={} memberId={}", owner.getId(), owner.getMemberId());
263	    }
264	
265	    /**
266	     * Records the audit trail for a just-created owner: the human-readable {@code AUDIT} line and, through
267	     * {@link #emitOwnerCreatedEvent(Owner)}, the structured {@link OwnerCreatedEvent}. Holding both audit
268	     * outputs in one place - separate from the create flow that produced the owner - keeps the create
269	     * pipeline reading as "make the owner, then audit it", and gives the identifiers the audit carries a
270	     * single home.
271	     *
272	     * @param owner the persisted owner just created, with its derived fields populated
273	     */
274	    private void auditOwnerCreated(Owner owner) {
275	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
276	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel(owner));
277	        emitOwnerCreatedEvent(owner);
278	    }
279	
280	    /**
281	     * Emits the immutable structured {@link OwnerCreatedEvent} for a just-created owner as a JSON
282	     * object on the {@code AUDIT} logger, alongside the human-readable audit line. The event is
283	     * stamped with the next {@link #CREATE_SEQUENCE} value and carries the owner's current
284	     * {@linkplain #primaryIdentifier(Owner) primary identifier} and reported
