434	    /**
435	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
436	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} and
437	     * {@code capacityWarning} flags, the version-2 {@code identity} object grouping the owner's
438	     * {@code memberId}, {@code householdId} and {@code identityKey}, the {@code apiVersion} and the
439	     * {@code possibleDuplicate} pair), and re-applies the owner's
440	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
441	     * create endpoint and the single-owner read endpoint return their owner through this method, so
442	     * an owner is decorated identically on either path and each derived field is computed in exactly
443	     * one place.
444	     *
445	     * @param owner the persisted owner to represent
446	     * @return the owner DTO with its derived read-only fields populated
447	     */
448	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
449	        owner.setHouseholdSize(householdSize(owner));
450	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
451	        int membershipLevel = membershipLevel(owner);
452	        ownerDto.setMembershipLevel(membershipLevel);
453	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
454	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
455	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
456	        ownerDto.setApiVersion(OWNER_IDENTITY_API_VERSION);
457	        ownerDto.setIdentity(ownerIdentity(owner));
458	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
459	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
460	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
461	        ownerDto.setRiskFlag(riskFlag(owner));
462	        return ownerDto;
463	    }
