465	    /**
466	     * The version of the owner identity contract carried by the owner response as its top-level
467	     * {@code apiVersion}. Version {@code 2} is the release under which the owner's identifiers are
468	     * rederived with a version-2 algorithm (mixing in a fixed {@code 'V2'} version tag) and grouped
469	     * under the nested {@code identity} object.
470	     */
471	    private static final int OWNER_IDENTITY_API_VERSION = 2;
472	
473	    /**
474	     * Groups an owner's version-2 identifiers into the nested {@code identity} object carried by the
475	     * owner response: its stored {@link Owner#getMemberId() memberId} and
476	     * {@link Owner#getHouseholdId() householdId}, and its derived {@link #identityKey(Owner) identityKey}.
477	     * Holding the three identifiers together in one object - separate from the flat owner fields - keeps
478	     * the response's identity contract in one place, and the identity's {@code identityKey} is computed
479	     * from the same single source the create endpoint's duplicate check uses.
480	     *
481	     * @param owner the persisted owner whose identifiers are grouped
482	     * @return the owner's version-2 identity object
483	     */
484	    private OwnerIdentityDto ownerIdentity(Owner owner) {
485	        OwnerIdentityDto identity = new OwnerIdentityDto();
486	        identity.setMemberId(owner.getMemberId());
487	        identity.setHouseholdId(owner.getHouseholdId());
488	        identity.setIdentityKey(identityKey(owner));
489	        return identity;
490	    }
