492	    /**
493	     * Derives the read-only {@code riskFlag} for an owner: {@code true} when any of the soft risk
494	     * signals hold, otherwise {@code false}. The owner is at risk when it is a possible duplicate
495	     * (its {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} is set), when its email domain
496	     * is {@linkplain DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or when
497	     * its city is over its soft capacity (the same {@link #capacityWarning(String)} band that raises
498	     * {@code capacityWarning}). Combining the existing signals here keeps {@code riskFlag} as a single
499	     * derived summary computed in exactly one place alongside the fields it aggregates.
500	     *
501	     * @param owner the persisted owner to assess
502	     * @return {@code true} when any risk signal holds, otherwise {@code false}
503	     */
504	    private boolean riskFlag(Owner owner) {
505	        return owner.getPossibleDuplicateOf() != null
506	            || disposableEmailDomains.isDisposableAdjacent(owner.getEmail())
507	            || capacityWarning(owner.getCity());
508	    }
