510	    /**
511	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
512	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
513	     * routed through the controller so the create audit log and the single-owner response agree on one
514	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
515	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
516	     *
517	     * <p>Household ceiling: the reported level is capped at one above the current maximum
518	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
519	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
520	     * than the owner itself). With no existing household member no cap applies and the owner-local level
521	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
522	     * capped level), so it depends only on the members' own points and cannot recurse.
523	     *
524	     * @param owner the owner whose reported membership level is wanted
525	     * @return the owner's membership level, capped at one above its household maximum
526	     */
527	    private Integer membershipLevel(Owner owner) {
528	        int ownLevel = ownerMapper.membershipLevel(owner);
529	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
530	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
531	            .mapToInt(this::householdMemberLevel)
532	            .max();
533	        if (maxHouseholdLevel.isEmpty()) {
534	            return ownLevel;
535	        }
536	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
537	    }
538	
539	    /**
540	     * The owner-local membership level of a household member, used only as an input to the household
541	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
542	     * household size} is set from its household before the level is derived, so the member's household
543	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
544	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
545	     *
546	     * @param member an existing member of an owner's household
547	     * @return the member's owner-local membership level
548	     */
549	    private int householdMemberLevel(Owner member) {
550	        member.setHouseholdSize(householdSize(member));
551	        return ownerMapper.membershipLevel(member);
552	    }
