554	    /**
555	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
556	     * every later step - the required-field check, the persisted value and the response - sees the
557	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
558	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
559	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
560	     * steps that read the address.
561	     *
562	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
563	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
564	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
565	     * are preferred when present: the flat {@code address} returned is composed as the normalized
566	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
567	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
568	     * {@code address} retain its own normalized value.
569	     *
570	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
571	     */
572	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
573	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
574	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
575	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
576	        ownerFieldsDto.setAddressLine1(addressLine1);
577	        ownerFieldsDto.setAddressLine2(addressLine2);
578	        if (addressLine1 != null && !addressLine1.isBlank()) {
579	            String composed = addressLine2 != null && !addressLine2.isBlank()
580	                ? addressLine1 + " " + addressLine2
581	                : addressLine1;
582	            ownerFieldsDto.setAddress(composed);
583	        } else {
584	            ownerFieldsDto.setAddress(flatAddress);
585	        }
586	    }
