588	    /**
589	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
590	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
591	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
592	     * blank (e.g. {@code "   "}). The offending field names are reported through an
593	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
594	     * as a 400 response carrying an {@code errors} array of field names.
595	     *
596	     * @param ownerFieldsDto the submitted owner fields
597	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
598	     */
599	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
600	        List<String> blankFields = new ArrayList<>();
601	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
602	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
603	        addRequiredAddress(blankFields, ownerFieldsDto);
604	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
605	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
606	        if (!blankFields.isEmpty()) {
607	            throw new InvalidOwnerFieldsException(blankFields);
608	        }
609	    }
610	
611	    private void addIfBlank(List<String> blankFields, String field, String value) {
612	        if (value != null && value.isBlank()) {
613	            blankFields.add(field);
614	        }
615	    }
