617	    /**
618	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
619	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
620	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
621	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
622	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
623	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
624	     *
625	     * @param blankFields the accumulating list of blank required-field names
626	     * @param ownerFieldsDto the submitted owner fields
627	     */
628	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
629	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
630	            blankFields.add("address");
631	        }
632	    }
