657	    /**
658	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
659	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
660	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
661	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
662	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
663	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
664	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
665	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
666	     *
667	     * @param city the city of the owner being created
668	     * @param postcode the supplied postcode, or {@code null} when omitted
669	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
670	     */
671	    private void rejectInvalidPostcode(String city, String postcode) {
672	        if (postcode == null || postcode.isBlank()) {
673	            return;
674	        }
675	        Region.forCity(city).ifPresent(region -> {
676	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
677	                throw new InvalidOwnerPostcodeException(postcode, city);
678	            }
679	        });
680	    }
