682	    /**
683	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
684	     * the {@code memberId}.
685	     */
686	    private static final int MEMBER_ID_HASH_LENGTH = 8;
687	
688	    /**
689	     * Builds the unified {@code memberId} assigned to a newly created owner, formatted
690	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the owner's
691	     * {@linkplain #identityRegionCode(Owner) identity region code}; {@code FY} is the two-digit fiscal year of the owner's
692	     * (business-day-adjusted) {@code registrationDate} ({@link OwnerMapper#fiscalYearSegment(Owner)});
693	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
694	     * normalized telephone followed by its last name; and {@code CHK} is a single Luhn check digit over
695	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). When this base id
696	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
697	     * {@code n} of 2 or more that makes the result unique (e.g. {@code 'NSW261A2B3C4D5-2'}), so distinct
698	     * owners always receive distinct member ids.
699	     *
700	     * @param owner the owner being created, with its telephone already normalized and its registration
701	     *              date set
702	     * @return the formatted, de-duplicated member id
703	     */
704	    private String memberId(Owner owner) {
705	        String region = identityRegionCode(owner);
706	        String fiscalYear = ownerMapper.fiscalYearSegment(owner);
707	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), MEMBER_ID_HASH_LENGTH);
708	        String core = region + fiscalYear + hash8;
709	        String base = core + Luhn.checkDigit(core);
710	        return deduplicate(base, Owner::getMemberId);
711	    }
712	
713	    /**
714	     * The version-2 region code baked into an owner's identifiers: the plain region code resolved from
715	     * the owner's {@code postcode} (falling back to its {@code city}) through the shared
716	     * {@link Region#code(String, String)} - the same one place an owner's postcode and city are turned
717	     * into a region code - with the fixed {@link OwnerMapper#IDENTITY_VERSION_TAG 'V2' version tag}
718	     * prefixed. This is the region code as it is embedded <em>inside</em> the identifiers an owner is
719	     * issued (the {@code REGION} segment of its {@link #memberId(Owner) memberId}, e.g. {@code 'V2NSW'}),
720	     * held in one place so every identifier derived for an owner keys off the identical region and no
721	     * version-1 identifier is reproduced. It is distinct from the user-facing region reported as the
722	     * owner's {@code locality} (see {@link OwnerMapper#locality(Owner)}), which reads the plain region
723	     * code back out of the issued identity, without the version tag.
724	     *
725	     * @param owner the owner whose identity region code is wanted
726	     * @return the version-2 region code embedded in the owner's identifiers (the plain region code, or
727	     *         {@link Region#UNKNOWN_CODE} when neither the postcode nor the city resolves, prefixed with
728	     *         the {@code 'V2'} version tag)
729	     */
730	    private String identityRegionCode(Owner owner) {
731	        return OwnerMapper.IDENTITY_VERSION_TAG + Region.code(owner.getPostcode(), owner.getCity());
732	    }
733	
734	    /**
735	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
736	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
737	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
738	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
739	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
740	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
741	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
742	     * caller supplies only which identifier it de-duplicates.
743	     *
744	     * @param base the computed base identifier to make unique among existing owners
745	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
746	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
747	     */
748	    private String deduplicate(String base, Function<Owner, String> identifier) {
749	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
750	            .map(identifier)
751	            .filter(java.util.Objects::nonNull)
752	            .collect(java.util.stream.Collectors.toSet());
753	        if (!existing.contains(base)) {
754	            return base;
755	        }
756	        int n = 2;
757	        while (existing.contains(base + "-" + n)) {
758	            n++;
759	        }
760	        return base + "-" + n;
761	    }
