892	    /**
893	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
894	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
895	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
896	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
897	     * value - whether supplied in the request or defaulted to the server date - is stored as the
898	     * next business day, and every value derived from the registration date (such as the membership
899	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
900	     *
901	     * @param date the effective registration date
902	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
903	     */
904	    private LocalDate businessDay(LocalDate date) {
905	        while (isNonBusinessDay(date)) {
906	            date = date.plusDays(1);
907	        }
908	        return date;
909	    }
