918	        DayOfWeek dayOfWeek = date.getDayOfWeek();
919	        return dayOfWeek == DayOfWeek.SATURDAY
920	            || dayOfWeek == DayOfWeek.SUNDAY
921	            || PUBLIC_HOLIDAYS.contains(date);
922	    }
