976	    /**
977	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
978	     * The identity key is the SHA-256 hex digest over
979	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
980	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
981	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
982	     * owners with the same last name and postcode but <em>different</em> telephones have different
983	     * identity keys and are both allowed (the second is surfaced instead as a soft
984	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
985	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
986	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
987	     * reported through a {@link DuplicateOwnerIdentityException}, which the {@code ExceptionControllerAdvice}
988	     * renders as a 409 Conflict response.
989	     *
990	     * @param owner the fully-populated owner being created (telephone normalized, email set)
991	     * @throws DuplicateOwnerIdentityException if an existing (non-deleted) owner has the same identity key
992	     */
993	    private void rejectDuplicateIdentity(Owner owner) {
994	        String key = identityKey(owner);
995	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
996	        if (duplicate) {
997	            throw new DuplicateOwnerIdentityException(key);
998	        }
999	    }
