1001	    /**
1002	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
1003	     * first existing owner whose {@code identityKey} <em>differs</em> from this owner's yet whose
1004	     * {@code lastName} has the same {@linkplain Soundex#encode(String) Soundex code} and whose
1005	     * {@code postcode} is equal, or {@code null} when no such owner exists. Because the telephone is
1006	     * part of the identity key, an existing owner sharing this owner's last-name sound and postcode but
1007	     * carrying a different telephone has a different identity key: it is not a hard duplicate (it passed
1008	     * {@link #rejectDuplicateIdentity(Owner)}) and is surfaced here as a soft match instead. An existing
1009	     * owner with the <em>same</em> identity key would already have been rejected as a 409 and so is
1010	     * excluded by the differing-key condition. A blank {@code postcode} never matches, since two owners
1011	     * without a postcode do not share one. The captured id is stored on the new owner and surfaced as
1012	     * the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
1013	     *
1014	     * @param owner the fully-populated owner being created (telephone normalized)
1015	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
1016	     */
1017	    private Integer possibleDuplicateOf(Owner owner) {
1018	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
1019	            return null;
1020	        }
1021	        String key = identityKey(owner);
1022	        String lastNameSoundex = soundex.encode(owner.getLastName());
1023	        return this.clinicService.findAllOwners().stream()
1024	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode())
1025	                && lastNameSoundex.equals(soundex.encode(existing.getLastName()))
1026	                && !key.equals(identityKey(existing)))
1027	            .map(Owner::getId)
1028	            .filter(java.util.Objects::nonNull)
1029	            .findFirst()
1030	            .orElse(null);
1031	    }
