1033	    /**
1034	     * Reduces an owner to its derived {@code identityKey}: the full lower-case SHA-256 hex digest (see
1035	     * {@link Sha256Hasher#hex(String)}) over the version-2 input
1036	     * {@code 'V2|<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} - the fixed
1037	     * {@link OwnerMapper#IDENTITY_VERSION_TAG 'V2' version tag} mixed in ahead of
1038	     * the owner's telephone reduced to its canonical E.164 form (see
1039	     * {@link TelephoneNormalizer#canonicalize(String)}), the owner's normalized (lower-cased) email or
1040	     * the empty string when absent (see {@link EmailNormalizer#normalize(String)}), and the
1041	     * {@linkplain Soundex#encode(String) Soundex code} of the owner's last name, joined by {@code '|'}.
1042	     * Two owners are duplicates exactly when their whole identity keys are equal. The hashed input never
1043	     * contains {@code null} segments, so the create endpoint's single duplicate check compares this one
1044	     * value across owners.
1045	     *
1046	     * @param owner the owner to derive the identity key for
1047	     * @return the owner's identity key, a 64-character lower-case hex string
1048	     */
1049	    private String identityKey(Owner owner) {
1050	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
1051	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
1052	        String email = normalizedEmail == null ? "" : normalizedEmail;
1053	        String lastNameSoundex = soundex.encode(owner.getLastName());
1054	        return sha256Hasher.hex(OwnerMapper.IDENTITY_VERSION_TAG + "|"
1055	            + telephone + "|" + email + "|" + lastNameSoundex);
1056	    }
