1078	    /**
1079	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
1080	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
1081	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
1082	     * being created to the same canonical key and reject a match.
1083	     *
1084	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
1085	     * @param key the canonical key of the owner being created
1086	     * @return {@code true} if some existing owner shares the key
1087	     */
1088	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
1089	        return findExistingOwner(keyExtractor, key).isPresent();
1090	    }
