1092	    /**
1093	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
1094	     * count-based rules - the per-city capacity, the per-day create limit and the derived
1095	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
1096	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
1097	     * place and each rule supplies just its own predicate.
1098	     *
1099	     * @param predicate the condition an owner must satisfy to be counted
1100	     * @return the number of existing owners that satisfy the predicate
1101	     */
1102	    private long countOwners(Predicate<Owner> predicate) {
1103	        return this.clinicService.findAllOwners().stream()
1104	            .filter(predicate)
1105	            .count();
1106	    }
