1108	    /**
1109	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
1110	     * shared {@code householdId}.
1111	     */
1112	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
1113	
1114	    /**
1115	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
1116	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
1117	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
1118	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
1119	     *
1120	     * @param value the raw field value, or {@code null}
1121	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
1122	     */
1123	    private String canonicalizeHousehold(String value) {
1124	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
1125	    }
1126	
1127	    /**
1128	     * Number of leading hex characters of the household hash retained as the shared
1129	     * {@code householdId}.
1130	     */
1131	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1132	
1133	    /**
1134	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
1135	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the version-2
1136	     * SHA-256 hash of {@code 'V2' + '|' + normalizedLastName + '|' + postcode} - the fixed
1137	     * {@link OwnerMapper#IDENTITY_VERSION_TAG 'V2' version tag} mixed in (see
1138	     * {@link #canonicalizeHousehold(String)} for the last-name normalization) - so every owner with the
1139	     * same last name and postcode - regardless of casing or spacing - is automatically assigned the
1140	     * identical value, and no version-1 household id is reproduced. Owners without a postcode have no
1141	     * household basis and are given no household id ({@code null}).
1142	     *
1143	     * @param owner the owner being created
1144	     * @return the shared household identifier, or {@code null} when the owner has no postcode
1145	     */
1146	    private String householdId(Owner owner) {
1147	        String postcode = owner.getPostcode();
1148	        if (postcode == null || postcode.isBlank()) {
1149	            return null;
1150	        }
1151	        String key = OwnerMapper.IDENTITY_VERSION_TAG + HOUSEHOLD_KEY_DELIMITER
1152	            + canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1153	        return sha256Hasher.hexPrefix(key, HOUSEHOLD_ID_LENGTH);
1154	    }
