1163	     * @param owner the owner whose household size is being derived
1164	     * @return the number of owners in the owner's household (at least {@code 1})
1165	     */
1166	    private int householdSize(Owner owner) {
1167	        if (owner.getHouseholdId() == null) {
1168	            return 1;
1169	        }
1170	        return householdMembers(owner).size();
